import torch, copy
import numpy as np

generated_inputs = {}

def flatten_inputs():
    list_of_inputs = []

    input1 = torch.randn(32, 1, 5, 5).numpy()
    input_dict1 = {
        "input": input1,
        "start_dim": 1,
        "end_dim": -1
    }
    list_of_inputs.append(copy.deepcopy(input_dict1))

    input2 = torch.randn(32, 1, 5, 5).numpy()
    input_dict2 = {
        "input": input2,
        "start_dim": 0,
        "end_dim": 2
    }
    list_of_inputs.append(copy.deepcopy(input_dict2))

    input3 = torch.randn(2, 3, 4, 5, 6).numpy()
    input_dict3 = {
        "input": input3,
        "start_dim": 1,
        "end_dim": 3
    }
    list_of_inputs.append(copy.deepcopy(input_dict3))
    
    input4 = torch.randn(2, 3, 4).numpy()
    input_dict4 = {
        "input": input4,
        "start_dim": 0,
        "end_dim": -1
    }
    list_of_inputs.append(copy.deepcopy(input_dict4))

    input5 = torch.randn(1, 2, 3, 4).numpy()
    input_dict5 = {
        "input": input5,
        "start_dim": 2,
        "end_dim": 3
    }
    list_of_inputs.append(copy.deepcopy(input_dict5))
    
    input6 = torch.randint(0, 10, (2, 3, 4, 5)).numpy()
    input_dict6 = {
        "input": input6,
        "start_dim": 1,
        "end_dim": -2
    }
    list_of_inputs.append(copy.deepcopy(input_dict6))

    input7 = torch.randn(2, 3, 4, 5).double().numpy()
    input_dict7 = {
        "input": input7,
        "start_dim": 1,
        "end_dim": 2
    }
    list_of_inputs.append(copy.deepcopy(input_dict7))
    
    return list_of_inputs


generated_inputs["torch.nn.Flatten"] = flatten_inputs()

