    output_ratio = None
    return_indices = False
    input_dict = {
        "kernel_size": kernel_size,
        "output_size": output_size,
        "output_ratio": output_ratio,
        "return_indices": return_indices,
        "input": input
    }
    list_of_inputs.append(copy.deepcopy(input_dict))
    
    # Example 6: different batch size
