    A = np.random.rand(3, 3).astype(np.float32)
    B = np.random.rand(3).astype(np.float32)
    input_dict = {"A": A, "B": B, "left": True, "out": None}
    list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

