import torch, copy

def set_default_device_inputs():
    list_of_inputs = []

    input_dict = {
        "device": "cpu"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    if torch.cuda.is_available():
        input_dict = {
            "device": "cuda"
        }
        list_of_inputs.append(copy.deepcopy(input_dict))

        input_dict = {
            "device": "cuda:0"
        }
        list_of_inputs.append(copy.deepcopy(input_dict))

        if torch.cuda.device_count() > 1:
            input_dict = {
                "device": "cuda:1"
            }
            list_of_inputs.append(copy.deepcopy(input_dict))
    
    try:
        if torch.backends.mps.is_available():
            input_dict = {
                "device": "mps"
            }
            list_of_inputs.append(copy.deepcopy(input_dict))
    except:
        pass


    return list_of_inputs

