def torch_compile_inputs():
    list_of_inputs = []

    def simple_func(x):
        return torch.sin(x) + torch.cos(x)

    input_dict = {
        "model": simple_func,
        "fullgraph": False,
        "dynamic": None,
        "backend": "inductor",
        "mode": "default",
        "options": None,
        "disable": False
    }

    def complex_model(x, y):
        z = torch.matmul(x, y)
        z = torch.relu(z)
        z = torch.add(z, 1)
        return z
    
    return list_of_inputs

