    padding = 1
    stride = 1
    L_h = (output_size[0] + 2 * padding - dilation * (kernel_size[0] - 1) - 1) // stride + 1
    L_w = (output_size[1] + 2 * padding - dilation * (kernel_size[1] - 1) - 1) // stride + 1
