    input_dict4 = {"input": input4, "padding": padding4}
    list_of_inputs.append(copy.deepcopy(input_dict4))
    
    # Input 5:  C,H,W format with tuple padding
    input5 = np.arange(12, dtype=np.float32).reshape(3, 2, 2)
