def convert_to_torch_type(input_dict):
    new_dict = {}
    for key, value in input_dict.items():
        if key == "dtype":
            new_dict[key] = value
        elif key == "length":
            new_dict[key] = int(value)
        elif key == "beta":
            new_dict[key] = float(value)
        elif key == "periodic":
            new_dict[key] = bool(value)
        elif key == "requires_grad":
            new_dict[key] = bool(value)
        elif key == "layout":
            new_dict[key] = None # layout can be None
        else:
            new_dict[key] = value
    return new_dict

