    stride = (1, 1)
    input_tensor = torch.randn(1, 3 * 2 * 2, 12).numpy()
    input_dict = {"output_size": output_size, "kernel_size": kernel_size, "dilation": dilation, "padding": padding, "stride": stride, "input": input_tensor}
